<script>const menu=document.querySelector('.home-menu'),links=document.getElementById('homeLinks');function closeMenu(){links.classList.remove('is-open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Buka navigasi');}menu.addEventListener('click',()=>{const open=links.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Tutup navigasi':'Buka navigasi');});links.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&links.classList.contains('is-open')){closeMenu();menu.focus();}});matchMedia('(min-width:901px)').addEventListener('change',closeMenu);</script></body></html>
